#!/usr/bin/env bash
# Regenerates v1/beacon.txt: beacons a desktop must accept or reject. It
# reuses the inputs of v1/pairing.txt (run pairing.sh first if they change)
# and checks the rules of docs/protocol.md, section "Beacons": exact length,
# magic, version, port, tag and the 15-minute window. Needs openssl and xxd.
set -euo pipefail
cd "$(dirname "$0")"

text() { printf '%s' "$1" | xxd -p -c 1000; }
hmac() { xxd -r -p <<<"$2" | openssl dgst -sha256 -mac HMAC -macopt "hexkey:$1" -binary | xxd -p -c 1000; }
input() { sed -n "s/^$1 = //p" v1/pairing.txt; }

presence_key=$(input presence_key)
secret=$(input secret)
port=$(input beacon_port)
now=$(input beacon_time)
nonce=$(input beacon_nonce)

# A beacon: $1 key, $2 flags (hex byte), $3 port, $4 unix time, $5 version (hex byte).
seal() {
  local head
  head=$(text L2LB)$5$2$(printf '%04x%016x' "$3" "$4")$nonce
  echo "$head$(hmac "$1" "$(text l2l-beacon-v1)$head" | cut -c1-32)"
}
good=$(seal "$presence_key" 00 "$port" "$now" 01)

{
  echo "# Beacon test vector; see README.md. Generated by beacon.sh."
  echo "# Lines are \"name = hex\". The desktop's clock is \"now\", and it holds"
  echo "# presence_key as the key of one paired phone and secret as the secret"
  echo "# of its active QR offer. The prefix of each name says what a desktop"
  echo "# must do: accept, reject silently, or reject with a clock-skew hint."
  echo
  echo "now = $now"
  echo "presence_key = $presence_key"
  echo "secret = $secret"
  echo
  echo "# Accepted"
  echo "accept_paired = $good"
  echo "accept_pairing = $(seal "$secret" 01 "$port" "$now" 01)"
  echo "accept_reserved_flags = $(seal "$presence_key" 06 "$port" "$now" 01)"
  echo "accept_window_early_edge = $(seal "$presence_key" 00 "$port" $((now - 900)) 01)"
  echo "accept_window_late_edge = $(seal "$presence_key" 00 "$port" $((now + 900)) 01)"
  echo
  echo "# Rejected: the tag does not verify, or the beacon is malformed"
  echo "reject_tag_bit_flipped = ${good:0:79}$(printf '%x' $((16#${good:79:1} ^ 1)))"
  echo "reject_wrong_key = $(seal "$secret" 00 "$port" "$now" 01)"
  echo "reject_pairing_flag_with_presence_key = $(seal "$presence_key" 01 "$port" "$now" 01)"
  echo "reject_magic = 4c324c43${good:8}"
  echo "reject_version_2 = $(seal "$presence_key" 00 "$port" "$now" 02)"
  echo "reject_port_zero = $(seal "$presence_key" 00 0 "$now" 01)"
  echo "reject_short = ${good:0:78}"
  echo "reject_long = ${good}00"
  echo "reject_empty = "
  echo
  echo "# Rejected: valid tag, outside the window (the desktop logs a clock hint)"
  echo "skew_past = $(seal "$presence_key" 00 "$port" $((now - 901)) 01)"
  echo "skew_future = $(seal "$presence_key" 00 "$port" $((now + 901)) 01)"
} > v1/beacon.txt
echo "wrote v1/beacon.txt"
